-- =============================================================================================
-- Carga de SIMULAÇÃO: seis meses de funcionamento fictício da casa (05/04/2026 a 29/09/2026).
-- GERADO por scripts/simulacao/gerar_simulacao.py — não editar à mão; gere de novo.
-- Tudo o que esta carga grava fica listado em simulacao_registro, e remover-simulacao.sql apaga
-- exatamente isso. Roda numa transação só: ou entra tudo, ou nada.
-- =============================================================================================
\set ON_ERROR_STOP on
SET client_encoding = 'UTF8';
BEGIN;

DO $$
BEGIN
  IF to_regclass('public.simulacao_registro') IS NOT NULL THEN
    RAISE EXCEPTION 'A simulação já está carregada neste banco (tabela simulacao_registro existe). Rode remover-simulacao.sql antes de carregar de novo.';
  END IF;
  IF EXISTS (SELECT 1 FROM sessao_assistencia WHERE data BETWEEN DATE '2026-04-05' AND DATE '2026-10-02')
     OR EXISTS (SELECT 1 FROM sessao_tratamento WHERE data_consulta BETWEEN DATE '2026-04-05' AND DATE '2026-10-02')
     OR EXISTS (SELECT 1 FROM prelecao WHERE data_apresentacao BETWEEN DATE '2026-04-05' AND DATE '2026-10-02')
     OR EXISTS (SELECT 1 FROM avaliacao WHERE data BETWEEN DATE '2026-04-05' AND DATE '2026-10-02')
     OR EXISTS (SELECT 1 FROM entrevista WHERE data BETWEEN DATE '2026-04-05' AND DATE '2026-10-02') THEN
    RAISE EXCEPTION 'Já existem sessões, presenças, preleções, avaliações ou entrevistas entre 05/04/2026 e 02/10/2026. A simulação não mistura dados com um período que já tem registros reais.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'entrevista' AND column_name = 'tipo') THEN
    RAISE EXCEPTION 'Este banco ainda não tem a migration V43 (tipos de entrevista). Publique a versão do sistema que a traz e rode a carga depois.';
  END IF;
  IF (SELECT count(*) FROM tipo_tratamento WHERE codigo IN ('P1','P2','P3A (ou P3F)','P3C','P3E','P3DC / P3V','A2','CH','P4','P3B')) <> 10 THEN
    RAISE EXCEPTION 'O catálogo de tratamentos não tem os 10 códigos esperados (V3 + V31).';
  END IF;
  IF EXISTS (SELECT 1 FROM assistido WHERE lower(email) LIKE '%@sim.invalid') THEN
    RAISE EXCEPTION 'Já há cadastros com e-mail @sim.invalid neste banco.';
  END IF;
END $$;

CREATE TABLE simulacao_registro (
    tabela      VARCHAR(40) NOT NULL,
    registro_id BIGINT      NOT NULL,
    carregado_em TIMESTAMP  NOT NULL DEFAULT now(),
    PRIMARY KEY (tabela, registro_id)
);
COMMENT ON TABLE simulacao_registro IS 'Linhas gravadas pela carga de simulação (scripts/simulacao). remover-simulacao.sql apaga essas linhas e esta tabela.';

-- sid(tabela, chave): o id real de cada registro da carga, tirado da sequência da própria tabela
-- (o sistema continua numerando normalmente depois) e anotado em simulacao_registro.
CREATE TEMP TABLE sim_ids (tabela TEXT, k INT, id BIGINT, PRIMARY KEY (tabela, k)) ON COMMIT DROP;
CREATE FUNCTION pg_temp.sid(t TEXT, chave INT) RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE novo BIGINT;
BEGIN
  SELECT id INTO novo FROM sim_ids WHERE tabela = t AND k = chave;
  IF novo IS NULL THEN
    novo := nextval(pg_get_serial_sequence(t, 'id'));
  END IF;
  RETURN novo;
END $$;
CREATE FUNCTION pg_temp.tt(c TEXT) RETURNS BIGINT LANGUAGE sql STABLE AS $$ SELECT id FROM tipo_tratamento WHERE codigo = c $$;

-- 163 cadastros (assistidos, trabalhadores e preletores convidados)

-- 36 trabalhadores (18 por dia) e as funções de cada um

-- preleções (uma por sessão; as das sessões canceladas ficam canceladas)

-- sessões de assistência: domingos 08h e terças 19h, todas encerradas (ou canceladas)

-- escala das sessões (767 posições preenchidas, sempre com o mínimo de cada setor)

-- 2454 presenças (efetivas e de ouvinte)

-- 411 avaliações e 524 entrevistas (392 de tratamento, 132 da 1ª sessão ou excepcionais)

-- 442 cartões encerrados (histórico de tratamentos)
-- 165 registros de dia de assistência

SELECT tabela, count(*) AS registros FROM simulacao_registro GROUP BY tabela ORDER BY tabela;
COMMIT;
